-- 실명·헌금 종류를 추정하지 않는 통장 가져오기용 표시 항목이다.
EXECUTE IMMEDIATE 'ALTER TABLE CONTACT ALTER COLUMN ID RESTART WITH ' || (SELECT GREATEST(COALESCE(MAX(ID),0)+1,COALESCE((SELECT IDENTITY_BASE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='CONTACT' AND COLUMN_NAME='ID'),1)) FROM CONTACT);
INSERT INTO CONTACT(TYPE,NAME,REMARKS,IS_HIDDEN) SELECT 'OTHER','통장거래(미분류)','통장 가져오기용. 실제 헌금자·수취인은 확인 후 변경하세요.',FALSE WHERE NOT EXISTS(SELECT 1 FROM CONTACT WHERE NAME='통장거래(미분류)');
